import{_ as r,C as s,c as a,o as i,a3 as n,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Internal transfers","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/operations/internal-transfers.md","filePath":"master/supply-chain/inventories/operations/internal-transfers.md","lastUpdated":1792041590000}'),l={name:"master/supply-chain/inventories/operations/internal-transfers.md"};function g(c,t,h,d,m,u){const e=s("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=n('<h1 id="internal-transfers" tabindex="-1">Internal transfers <a class="header-anchor" href="#internal-transfers" aria-label="Permalink to &quot;Internal transfers&quot;">​</a></h1><p>An internal transfer moves stock from one location to another inside your company. Use it to restock a picking shelf, move goods to a quality area or tidy a warehouse. It changes where stock sits, not how much you own.</p><blockquote><p><strong>In simple words:</strong> An internal transfer is &quot;take these from shelf A and put them on shelf B&quot;.</p></blockquote><p>Open <code>Inventory → Operations → Transfers → Internal Transfers</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The menu needs <strong>Locations</strong> on. Go to <code>Inventory → Settings → Manage Warehouses</code>, turn on <strong>Locations</strong> and click <strong>Save changes</strong>. See <a href="./../warehouses/locations.html">Locations</a>.</p><h2 id="create-an-internal-transfer" tabindex="-1">Create an internal transfer <a class="header-anchor" href="#create-an-internal-transfer" aria-label="Permalink to &quot;Create an internal transfer&quot;">​</a></h2><p>Example: move 20 <strong>Camping Hammock</strong> from <strong>WH/Stock</strong> to <strong>WH/Packing Zone</strong>.</p><ol><li>Click <strong>New Internal Transfer</strong>.</li><li>Fill <strong>Contact</strong> if needed. Choose the <strong>Operation Type</strong>. The default is <strong>My Company: Pick</strong>. The list also has <strong>Receipts</strong>, <strong>Delivery Orders</strong>, <strong>Pack</strong>, <strong>Quality Control</strong>, <strong>Storage</strong> and <strong>Internal Transfers</strong>. <strong>Internal Transfers</strong> (prefix <strong>INT</strong>) is the plain choice. With the default <strong>Pick</strong> type, the number looks like <strong>WH/PICK/00010</strong>, not <strong>INT</strong>.</li><li>Set <strong>Source Location</strong> and <strong>Destination Location</strong>. Defaults are <strong>WH/Stock</strong> and <strong>WH/Packing Zone</strong>.</li></ol>',9)),o(e,{src:"/images1/inventory/int_create.png",alt:"Create Internal Transfer form with Camping Hammock quantity 20 from WH/Stock to WH/Packing Zone"}),t[1]||(t[1]=n('<ol start="4"><li>In the <strong>Operations</strong> tab, click <strong>Add to moves</strong>. Pick the <strong>Product</strong>, set <strong>Demand</strong> to 20 and check the <strong>Unit</strong>.</li><li>Click <strong>Create</strong>. The form also offers <strong>Create &amp; create another</strong> and <strong>Cancel</strong>. You stay on the <strong>Edit</strong> page, and the <strong>Packaging</strong> column fills in by itself, for example <strong>Pack Of → 20</strong>.</li><li>Click <strong>Mark as Todo</strong>. With stock available, the state goes straight to <strong>Ready</strong>. If the state is <strong>Waiting</strong>, click <strong>Check Availability</strong>.</li><li>When the state is <strong>Ready</strong>, click <strong>Validate</strong>. The buttons on a <strong>Ready</strong> transfer are <strong>Validate</strong>, <strong>Cancel</strong>, <strong>Print</strong> and <strong>Delete</strong>.</li></ol>',1)),o(e,{src:"/images1/inventory/int_validate.png",alt:"Internal transfer in Ready state with Validate button"}),t[2]||(t[2]=n('<p>The state becomes <strong>Done</strong> and the hammocks now sit in <strong>WH/Packing Zone</strong>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><ul><li><strong><em>Contact:</em></strong> Optional partner.</li><li><strong><em>Operation Type</em></strong>, <strong><em>Source Location</em></strong>, <strong><em>Destination Location</em></strong>: required.</li><li><strong><em>Responsible</em></strong>, <strong><em>Scheduled At</em></strong>, <strong><em>Source Document</em></strong>: on the <strong>Additional</strong> tab.</li><li>Table columns match receipts. See <a href="./receipts.html">Receipts</a>.</li></ul><h2 id="automatic-internal-transfers" tabindex="-1">Automatic internal transfers <a class="header-anchor" href="#automatic-internal-transfers" aria-label="Permalink to &quot;Automatic internal transfers&quot;">​</a></h2><p>Warehouses with extra steps create internal documents for you. The example warehouse produces <strong>WH/PICK</strong>, <strong>WH/PACK</strong>, <strong>WH/QC</strong>, <strong>WH/STOR</strong>, <strong>WH/PC</strong> and <strong>WH/SFP</strong> records. They behave like any internal transfer. Open them from the same list. Click <strong>Next Transfer</strong> on a done document to jump to the one that follows.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Moving stock never changes the total on hand. Use <a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a> to change quantities.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>Buttons follow the common table in <a href="./">Transfers</a>: <strong>Mark as Todo</strong>, <strong>Check Availability</strong> (on <strong>Waiting</strong> only), <strong>Validate</strong>, <strong>Cancel</strong>, <strong>Print</strong>, <strong>Delete</strong>, <strong>Return</strong> and <strong>Next Transfer</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Transfers</a></li><li><a href="./../warehouses/locations.html">Locations</a></li><li><a href="./../routes/putaway-rules.html">Putaway rules</a></li></ul>',10))])}const k=r(l,[["render",g]]);export{f as __pageData,k as default};
